#include <cstdio>
using namespace std;

using ll = long long;

const ll MOD = 1000000007;
const ll PHI = MOD - 1;

ll modPow(ll base, ll exponent) {
    ll result = 1;
    while (exponent > 0) {
        if (exponent & 1LL)
            result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ll n, m;
    int k;
    scanf("%lld %lld %d", &n, &m, &k);

    if (((n & 1LL) != (m & 1LL)) && k == -1) {
        puts("0");
        return 0;
    }

    ll exponent = ((n - 1) % PHI) * ((m - 1) % PHI) % PHI;
    printf("%lld\n", modPow(2, exponent));
    return 0;
}

